package com.bank.batch;

import io.vertx.core.AbstractVerticle;
import io.vertx.core.WorkerExecutor;
import java.math.BigDecimal;
import java.util.List;
import java.util.logging.Logger;

public class BatchVerticle extends AbstractVerticle {
    private static final Logger log = Logger.getLogger(BatchVerticle.class.getName());
    private WorkerExecutor batchPool;

    @Override
    public void start() {
        // Dedicated, sized worker pool so batch work never starves other tasks.
        batchPool = vertx.createSharedWorkerExecutor("interest-batch-pool", 4);

        // setPeriodic stands in for a daily cron trigger (e.g. 02:00 every day).
        // In production: parse cron → setTimer to next 02:00 → re-arm, + cluster lock.
        long everyFiveSeconds = 5000;
        vertx.setPeriodic(everyFiveSeconds, timerId -> {
            log.info(() -> "Cron trigger fired (timer=" + timerId + ") — submitting batch to worker pool");

            // Heavy job runs on the WORKER POOL, never on the event loop.
            batchPool.executeBlocking(promise -> {
                InterestBatchJob job = new InterestBatchJob();
                List<Account> accounts = List.of(
                    new Account("SAV2001", "Rajesh Kumar", new BigDecimal("1000000")),
                    new Account("CUR3001", "Priya Sharma", new BigDecimal("250000")));
                BigDecimal totalPosted = job.postDailyInterest(accounts);
                promise.complete(totalPosted);
            }, false) // false = parallel, unordered batches allowed
            .onSuccess(total -> log.info(() -> "Batch complete. Total interest posted: Rs." + total))
            .onFailure(err  -> log.severe("Batch failed: " + err.getMessage()));
        });
        log.info("Interest batch scheduled.");
    }

    @Override
    public void stop() {
        if (batchPool != null) batchPool.close();
    }
}
