package com.bank.batch;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.List;
import java.util.logging.Logger;

// Blocking job — safe because it runs on the worker pool.
public class InterestBatchJob {
    private static final Logger log = Logger.getLogger(InterestBatchJob.class.getName());
    // 4% annual → daily rate; all money in BigDecimal.
    private static final BigDecimal DAILY_RATE =
        new BigDecimal("0.04").divide(new BigDecimal("365"), 10, RoundingMode.HALF_UP);

    public BigDecimal postDailyInterest(List<Account> accounts) {
        BigDecimal total = BigDecimal.ZERO;
        for (Account acc : accounts) {
            // Idempotent, chunk-friendly: simulate a blocking DB write per account.
            try { Thread.sleep(20); } catch (InterruptedException e) { Thread.currentThread().interrupt(); }
            BigDecimal interest = acc.getBalance().multiply(DAILY_RATE).setScale(2, RoundingMode.HALF_UP);
            acc.credit(interest);
            total = total.add(interest);
            log.fine(() -> "Posted Rs." + interest + " to " + acc.getAccountId()
                    + " new bal Rs." + acc.getBalance());
            log.info(() -> "Interest posted: " + acc.getAccountId() + " += Rs." + interest);
        }
        return total.setScale(2, RoundingMode.HALF_UP);
    }
}
